    b = config.get('body') or dict()
    raw = str(b.get('answer') or '').strip()
    out = raw
    m = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})$', raw)
    if m:
        out = '%04d-%02d-%02d' % (int(m.group(1)), int(m.group(2)), int(m.group(3)))
    else:
        m = re.match(r'^(\d{1,2})[./ -](\d{1,2})[./ -](\d{2,4})$', raw)
        if m:
            a, c, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if y < 100:
                y = y + (1900 if y > 30 else 2000)
            day, mon = (a, c) if 'DMY' == 'DMY' else (c, a)
            out = '%04d-%02d-%02d' % (y, mon, day)
    b['answer'] = out
    config['body'] = b
except Exception:
    pass

