def handle_amount_then_agree(p, amt, d, st, today):
    a = target_amount(p) if amt is None else amt
    res = check_amount(p, a, st, today, d)
    if res is not None:
        return res
    if a > p["full"]:
        a = p["full"]
    return agree(p, a, d)
def make_offer(p, amount, d, reason, latest=False):
    p["status"] = "offered"
